import { BrushTool } from "./Brush.js";
export class AdvancedBrush extends BrushTool {
    tasks;
    _location = [0, 0, 0, 0];
    constructor(tasks) {
        super();
        this.tasks = tasks;
    }
    mode = "async";
    _mapLocation() {
        this._location[0] = this.dimension;
        this._location[1] = this.x;
        this._location[2] = this.y;
        this._location[3] = this.z;
    }
    setMode(mode) {
        this.mode = mode;
        return this;
    }
    paintAndAwaitUpdate() {
        return new Promise((resolve) => {
            this.paintAndUpdate(() => {
                resolve(true);
            });
        });
    }
    eraseAndAwaitUpdate() {
        const self = this;
        return new Promise((resolve) => {
            self.eraseAndUpdate(() => {
                resolve(true);
            });
        });
    }
    paintAndUpdate(onDone) {
        this._mapLocation();
        this.tasks.voxel.paint.run([this._location, this.getRaw(), {}], null, () => {
            if (onDone)
                onDone();
        });
    }
    eraseAndUpdate(onDone) {
        this._mapLocation();
        this.tasks.voxel.erase.run([this._location, {}], null, () => {
            if (onDone)
                onDone();
        });
    }
}
